<template><section class="expense-form"><el-alert v-if="publicMode" title="免登录报账入口：提交后由财务核验，不提供其他人员报账查询。" type="info" :closable="false"/><el-result v-if="receipt" icon="success" title="报账已提交" sub-title="请保留提交凭据，勿重复录入"><template #extra><p class="receipt">{{receipt}}</p><el-button type="primary" @click="again">继续填写另一笔</el-button></template></el-result><el-form v-else ref="refForm" :model="form" :rules="rules" label-position="top" :disabled="saving"><div class="expense-grid"><el-form-item label="报账金额（元）" prop="amount"><el-input v-model="form.amount" inputmode="decimal" placeholder="例如 128.50" maxlength="19"/></el-form-item><el-form-item label="日期" prop="expenseDate"><el-date-picker v-model="form.expenseDate" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item><el-form-item label="报账人" prop="userId"><FinancePicker v-model="form.userId" placeholder="选择报账人" :clearable="false" @select="validateUser" :loader="name=>expenseOptions('users',name,publicMode)"/></el-form-item><el-form-item label="关联项目（可不关联）"><FinancePicker v-model="form.projectId" placeholder="选择关联项目（可不关联）" :loader="name=>expenseOptions('projects',name,publicMode)" hint="可直接选择，或输入项目名称、编号搜索。"/></el-form-item></div><el-form-item label="用途" prop="purpose"><el-input v-model="form.purpose" type="textarea" :rows="3" maxlength="2000" show-word-limit placeholder="填写费用用途、现场事项或采购内容"/></el-form-item><el-form-item label="发票 / 凭证"><div><el-button size="large" @click="fileInput.click()">选择发票 / 拍照</el-button><span style="margin-left:12px;color:#65748b">已选 {{invoices.length}} / 5</span><input ref="fileInput" style="display:none" type="file" accept="application/pdf,image/png,image/jpeg" multiple @change="chooseFiles"/><p class="hint">PDF、JPG、PNG，最多5个文件，每个不超过10MB。可拍照后选择图片。</p><ul><li v-for="(f,i) in invoices" :key="i">{{f.name}} <el-button link type="danger" @click="invoices.splice(i,1)">移除</el-button></li></ul></div></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" :rows="2" maxlength="2000"/></el-form-item><el-button type="primary" size="large" :loading="saving" @click="submit" class="submit-expense">提交报账</el-button><p class="hint">{{publicMode?'免登录提交会标记为待核验；请准确选择实际报账人。':'可代其他员工录入，系统同时记录当前录入账号。'}}</p></el-form></section></template>
<script setup>
import {submitExpense,expenseOptions} from '@/api/projectFinance';import FinancePicker from './FinancePicker.vue';import {ElMessage,ElMessageBox} from 'element-plus';import {onBeforeRouteLeave} from 'vue-router';
function newToken(){const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const h=Array.from(bytes,x=>x.toString(16).padStart(2,'0')).join('');return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`}
const props=defineProps({publicMode:Boolean});const refForm=ref(),fileInput=ref(),saving=ref(false),receipt=ref(''),users=ref([]),projects=ref([]),invoices=ref([]);const form=reactive({amount:'',purpose:'',userId:null,projectId:null,expenseDate:new Date().toLocaleDateString('sv-SE'),remark:''});let token=newToken(),userSeq=0,projectSeq=0;
const rules={amount:[{required:true,message:'请填写金额',trigger:'blur'},{validator:(_r,v,cb)=>/^\d+(\.\d{1,2})?$/.test(v)&&Number(v)>0?cb():cb(new Error('请填写大于0且最多两位小数的金额')),trigger:'blur'}],purpose:[{required:true,message:'请填写用途',trigger:'blur'}],userId:[{required:true,message:'请选择报账人',trigger:'change'}],expenseDate:[{required:true,message:'请选择日期',trigger:'change'}]};
function validateUser(){nextTick(()=>refForm.value?.validateField('userId').catch(()=>{}))}
function chooseFiles(event){const files=[...event.target.files];if(files.some(f=>f.size>10*1024*1024)||invoices.value.length+files.length>5){ElMessage.error('最多5个文件，每个不得超过10MB');event.target.value='';return}invoices.value.push(...files);event.target.value=''}
async function submit(){if(saving.value||!await refForm.value.validate().catch(()=>false))return;saving.value=true;try{const data=new FormData();for(const [k,v] of Object.entries(form))if(v!==null&&v!=='')data.append(k,v);data.append('clientToken',token);for(const f of invoices.value)data.append('invoices',f);const r=await submitExpense(data,props.publicMode);receipt.value=r.data.receipt;invoices.value=[]}finally{saving.value=false}}
function again(){receipt.value='';Object.assign(form,{amount:'',purpose:'',projectId:null,remark:''});token=newToken()}
onBeforeRouteLeave(async()=>{if(saving.value)return false;if(!receipt.value&&(form.amount||form.purpose||invoices.value.length)){try{await ElMessageBox.confirm('离开并放弃未提交的报账？')}catch{return false}}return true});
</script><style scoped>.expense-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 20px}.hint{color:#65748b;font-size:12px;line-height:1.8}.receipt{overflow-wrap:anywhere}.submit-expense{min-width:160px}@media(max-width:650px){.expense-grid{grid-template-columns:1fr}.submit-expense{width:100%}.expense-form :deep(.el-input__wrapper){min-height:42px}.expense-form :deep(.el-form-item){margin-bottom:22px}}</style>
